// The window, the buffers, Flip, and information about the graphics.

#include "graphics_internal.hpp"

using namespace bb::gfx;

extern "C" {

// Graphics width, height, depth, mode.
// Modes: 0 = windowed (or fullscreen for 3D), 1 = fullscreen, 2 = windowed, 3 = resizable window.
void bb_graphics(int32_t width, int32_t height, int32_t depth, int32_t mode)
{
	(void)depth;
	if ((width <= 0) || (height <= 0)) {
		fail("Graphics needs a width and height of at least 1.");
	}
	if (g.created) {
		bb_end_graphics();
	}

	g.headless = getenv("BLITZ_HEADLESS") != nullptr;
	g.width    = uint32_t(width);
	g.height   = uint32_t(height);
	g.created  = true;
	g.target   = back_buffer;
	if (g.headless) {
		return;
	}

	if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_EVENTS)) {
		fail(SDL_GetError());
	}
	SDL_WindowFlags flags = SDL_WINDOW_VULKAN;
	if (mode == 1) {
		flags |= SDL_WINDOW_FULLSCREEN;
	} else if (mode == 3) {
		flags |= SDL_WINDOW_RESIZABLE;
	}
	g.window = SDL_CreateWindow("BlitzLLVM", width, height, flags);
	if (!g.window) {
		fail(SDL_GetError());
	}
	SDL_StartTextInput(g.window);

	create_vulkan();
	create_buffers(uint32_t(width), uint32_t(height));
	create_swapchain();
}

void bb_end_graphics(void)
{
	if (!g.created) {
		return;
	}
	if (!g.headless) {
		flush(); // What was asked for is drawn before it all goes away.
		vkDeviceWaitIdle(g.device);
		for (int i = 0; i < 2; i++) {
			destroy_image(g.buffers[i]);
		}
		for (uint32_t i = 0; i < texture_table.size; i++) {
			if (texture_table[i].used) {
				free_texture(texture_table[i]);
			}
		}
		for (uint32_t i = 0; i < image_table.size; i++) {
			if (image_table[i].used) {
				free_image(image_table[i]);
			}
		}
		for (uint32_t i = 0; i < max_depths; i++) {
			destroy_image(depth_cache[i]);
		}
		if (scratch) {
			vkDestroyBuffer(g.device, scratch, nullptr);
			vkFreeMemory(g.device, scratch_memory, nullptr);
			scratch = VK_NULL_HANDLE;
			scratch_size = 0;
		}
		empty_graveyard();
		vkDestroyBuffer(g.device, g.scene_buffer, nullptr);
		vkFreeMemory(g.device, g.scene_memory, nullptr);
		vkDestroyPipeline(g.device, g.opaque3d, nullptr);
		vkDestroyPipeline(g.device, g.blend3d, nullptr);
		vkDestroyPipeline(g.device, g.mul3d, nullptr);
		vkDestroyPipeline(g.device, g.mul2x3d, nullptr);
		vkDestroyPipeline(g.device, g.add3d, nullptr);
		for (VkPipeline pipeline : g.wire3d) {
			if (pipeline) {
				vkDestroyPipeline(g.device, pipeline, nullptr);
			}
		}
		vkDestroyPipelineLayout(g.device, g.layout3d, nullptr);
		vkDestroyDescriptorSetLayout(g.device, g.scene_layout, nullptr);
		for (int i = 0; i < TEXTURES; i++) {
			destroy_image(g.textures[i]);
		}
		destroy_swapchain();
		vkDestroyBuffer(g.device, g.vertex_buffer, nullptr);
		vkFreeMemory(g.device, g.vertex_memory, nullptr);
		vkDestroyPipeline(g.device, g.triangles, nullptr);
		vkDestroyPipeline(g.device, g.lines, nullptr);
		vkDestroyPipelineLayout(g.device, g.layout, nullptr);
		vkDestroyDescriptorPool(g.device, g.set_pool, nullptr);
		vkDestroyDescriptorSetLayout(g.device, g.set_layout, nullptr);
		vkDestroySampler(g.device, g.sampler, nullptr);
		vkDestroySampler(g.device, g.sampler_repeat, nullptr);
		vkDestroySampler(g.device, g.sampler_clamp, nullptr);
		vkDestroySemaphore(g.device, g.acquired, nullptr);
		vkDestroyFence(g.device, g.fence, nullptr);
		vkDestroyCommandPool(g.device, g.pool, nullptr);
		vkDestroyDevice(g.device, nullptr);
		SDL_Vulkan_DestroySurface(g.instance, g.surface, nullptr);
		vkDestroyInstance(g.instance, nullptr);
		SDL_DestroyWindow(g.window);
		SDL_Quit();
	}
	free(g.ops);
	forget_recorded();
	g = state();
}

int32_t bb_graphics_width(void)
{
	return int32_t(g.width);
}

int32_t bb_graphics_height(void)
{
	return int32_t(g.height);
}

int32_t bb_front_buffer(void)
{
	return front_buffer;
}

int32_t bb_back_buffer(void)
{
	return back_buffer;
}

void bb_set_buffer(int32_t buffer)
{
	if (active() && !resolve_target(buffer).image) {
		fail("SetBuffer: the buffer does not exist.");
	}
	g.target = buffer; // What is drawn to it is only recorded for now, each operation knows its buffer.
}

void bb_app_title(const char* title, const char* close_prompt)
{
	(void)close_prompt;
	if (active()) {
		SDL_SetWindowTitle(g.window, title ? title : "");
	}
}

// Flip [vwait]: show what was drawn to the back buffer.
void bb_flip(int32_t vwait)
{
	bb::profile_scope timer(bb::PROFILE_FLIP);
	if (!active()) {
		return;
	}
	{
		// BLITZ_FPS=1 reports how many frames are shown each second.
		static int    enabled = -1;
		static Uint64 last    = 0;
		static int    frames  = 0;
		if (enabled < 0) {
			enabled = getenv("BLITZ_FPS") ? 1 : 0;
			bb::profile_start_sampler();
		}
		if (enabled) {
			frames++;
			Uint64 now = SDL_GetTicks();
			if (now - last >= 1000) {
				fprintf(stderr, "fps: %d, submits: %d, waiting: %.1f ms\n", frames, profile_submits, double(profile_wait) * 1000.0 / double(SDL_GetPerformanceFrequency()));
				for (int i = 0; i < bb::PROFILE_COUNT; i++) {
					fprintf(stderr, "  %s: %.1f ms\n", bb::profile_names[i], double(bb::profile_ticks[i]) * 1000.0 / double(SDL_GetPerformanceFrequency()));
					bb::profile_ticks[i] = 0;
				}
				profile_submits = 0;
				profile_wait    = 0;
				frames = 0;
				last   = now;
			}
		}
	}
	pump();
	flush();

	bool vsync = (vwait != 0);
	if (vsync != g.vsync) {
		g.vsync = vsync;
		g.resized = true;
	}
	ensure_swapchain();
	if (g.swapchain == VK_NULL_HANDLE) {
		return; // Minimized
	}
	begin_commands();
	present_front(true);
}

////////////////////////////////////////////////////////////////////////////////
// Information about the graphics
////////////////////////////////////////////////////////////////////////////////
int32_t bb_graphics_depth(void)
{
	return 32;
}

int32_t bb_gfx_mode_3d_exists(int32_t width, int32_t height, int32_t depth)
{
	(void)width;
	(void)height;
	(void)depth;
	return 1;
}

int32_t bb_windowed_3d(void)
{
	return 1;
}

// Video memory in bytes, as much as the GPU says it has (and what is left of it can't be asked for).
int32_t bb_total_vid_mem(void)
{
	if (!active()) {
		return 0;
	}
	uint64_t total = 0;
	for (uint32_t i = 0; i < g.memory.memoryHeapCount; i++) {
		if (g.memory.memoryHeaps[i].flags & VK_MEMORY_HEAP_DEVICE_LOCAL_BIT) {
			total += g.memory.memoryHeaps[i].size;
		}
	}
	return total > 0x7FFFFFFFull ? 0x7FFFFFFF : int32_t(total);
}

int32_t bb_avail_vid_mem(void)
{
	return bb_total_vid_mem();
}

int32_t bb_tris_rendered(void)
{
	return int32_t(g.triangles_drawn);
}

int32_t bb_active_textures(void)
{
	int32_t count = 0;
	for (uint32_t i = 0; i < texture_table.size; i++) {
		count += texture_table[i].used ? 1 : 0;
	}
	return count;
}
}
